<div class="modal fade" id="stationModal" tabindex="-1"><div class="modal-dialog modal-lg modal-dialog-scrollable"><div class="modal-content"><form method="post" action="/admin/stations"><div class="modal-header"><div><h2 class="modal-title fs-5" id="stationModalTitle">Add station</h2><div class="small text-body-secondary">Common settings stay the same; type-specific options appear below.</div></div><button class="btn-close" type="button" data-bs-dismiss="modal"></button></div><div class="modal-body"><input type="hidden" name="_csrf" value="<?= e($csrf) ?>"><input type="hidden" name="action" value="create"><input type="hidden" name="id" value="0"><input type="hidden" name="router_id" value="<?= e($router['id']) ?>"><input type="hidden" name="base_url" value=""><div class="row g-3"><div class="col-md-6"><label>Name / Wi-Fi name</label><input name="name" required maxlength="160"></div><div class="col-md-6"><label>Station type</label><select name="station_type" id="station-type" required><option value="hotspot">Hotspot</option><option value="vendo_gateway">Vendo Gateway</option></select></div><div class="col-md-6"><label>Portal theme</label><select name="portal_theme_id"><option value="0">Inherit router theme</option><?php foreach($themes as $theme):?><option value="<?= e($theme['id']) ?>"><?= e($theme['name']) ?></option><?php endforeach;?></select></div><div class="col-md-6"><label>Server IP</label><input name="server_ip" required placeholder="10.0.3.1"></div><div class="col-md-6"><label>Client subnet</label><input name="client_subnet" placeholder="10.0.3.0/24"></div><div class="col-md-6"><label>Interface</label><input name="interface_name" placeholder="bridge-HS"></div><div class="col-md-6"><label>Password mode</label><select name="password_mode"><option value="blank">Blank password</option><option value="voucher">Voucher as password</option></select></div><div class="col-12 d-none" id="vendo-gateway-options"><div class="border rounded p-3"><div class="d-flex align-items-center justify-content-between gap-2 mb-3"><div><div class="fw-semibold">Vendo Gateway</div><div class="small text-body-secondary" id="vendo-gateway-status">Not paired</div></div><span class="badge text-bg-primary">Station type</span></div><div class="mb-3"><label>Gateway address</label><div class="input-group"><input class="form-control code" id="stationGatewayUrl" value="" readonly><button class="btn btn-outline-secondary" type="button" id="copyStationGatewayUrl">Copy</button></div><small class="text-body-secondary">Use this address during ESP initial setup. The device API is exposed under <code>/vendo/v1</code>.</small></div><div id="vendo-existing-options" class="d-none"><div class="alert alert-info py-2 mb-3">Generate a one-time setup code, then enter it in the ESP setup page. The code is valid for about 10 minutes and binds the device to this station.</div><button class="btn btn-outline-primary" type="submit" form="station-vendo-setup-form" id="station-setup-code">Generate setup code</button></div><div id="vendo-new-options" class="small text-body-secondary mb-3">Save this station first. Then edit it to generate its setup code.</div><div class="d-flex flex-wrap gap-4 mt-3"><label class="d-inline-flex align-items-center gap-2"><input class="form-check-input m-0" style="width:1rem;height:1rem" type="checkbox" name="charging_enabled" value="1"> Phone charging</label><label class="d-inline-flex align-items-center gap-2"><input class="form-check-input m-0" style="width:1rem;height:1rem" type="checkbox" name="eload_enabled" value="1"> E-load</label></div></div></div><div class="col-12"><label class="d-inline-flex align-items-center gap-2"><input class="form-check-input m-0" style="width:1rem;height:1rem" type="checkbox" name="enabled" value="1" checked> Enabled</label></div></div></div><div class="modal-footer"><button class="btn btn-outline-secondary" type="button" data-bs-dismiss="modal">Cancel</button><button class="button" type="submit" id="station-submit">Add station</button></div></form></div></div></div>
<script>
const fm=document.getElementById('featuresModal');fm?.addEventListener('show.bs.modal',e=>{const b=e.relatedTarget,f=fm.querySelector('form'),data=JSON.parse(b.dataset.features||'{}');f.querySelector('[name=id]').value=b.dataset.id;document.getElementById('feature-station-name').textContent=b.dataset.name;f.querySelectorAll('[data-feature]').forEach(s=>{const v=data[s.dataset.feature]?.value;s.value=v===true?'on':v===false?'off':'inherit';});f.querySelector('[name=trial_minutes]').value=data.trial?.config?.minutes||10;f.querySelector('[name=convert_points]').value=data.points_convert?.config?.points||10;f.querySelector('[name=convert_minutes]').value=data.points_convert?.config?.minutes||5;});
const sm=document.getElementById('stationModal'),stationType=document.getElementById('station-type'),gatewayOptions=document.getElementById('vendo-gateway-options'),gatewayExisting=document.getElementById('vendo-existing-options'),gatewayNew=document.getElementById('vendo-new-options'),gatewayStatus=document.getElementById('vendo-gateway-status'),gatewaySetupForm=document.getElementById('station-vendo-setup-form');
function syncStationType(){const f=sm.querySelector('form'),isGateway=stationType.value==='vendo_gateway',id=Number(f.querySelector('[name=id]').value||0);gatewayOptions.classList.toggle('d-none',!isGateway);gatewayExisting.classList.toggle('d-none',!isGateway||id<1);gatewayNew.classList.toggle('d-none',!isGateway||id>0);if(!isGateway){f.querySelector('[name=charging_enabled]').checked=false;f.querySelector('[name=eload_enabled]').checked=false;}gatewaySetupForm.querySelector('[name=vendo_id]').value=id>0?String(id):'';}
stationType?.addEventListener('change',syncStationType);
sm?.addEventListener('show.bs.modal',e=>{const b=e.relatedTarget,edit=b?.dataset.mode==='edit',f=sm.querySelector('form');f.reset();f.querySelector('[name=router_id]').value='<?= e($router['id']) ?>';f.querySelector('[name=action]').value=edit?'update':'create';f.querySelector('[name=id]').value=edit?b.dataset.id:'0';f.querySelector('[name=base_url]').value=edit?(b.dataset.url||''):'';stationType.value=edit?(b.dataset.type||'hotspot'):'hotspot';if(edit){f.querySelector('[name=name]').value=b.dataset.name;f.querySelector('[name=portal_theme_id]').value=b.dataset.theme;f.querySelector('[name=server_ip]').value=b.dataset.serverIp;f.querySelector('[name=client_subnet]').value=b.dataset.subnet;f.querySelector('[name=interface_name]').value=b.dataset.interface;f.querySelector('[name=password_mode]').value=b.dataset.passwordMode;f.querySelector('[name=charging_enabled]').checked=b.dataset.charging==='1';f.querySelector('[name=eload_enabled]').checked=b.dataset.eload==='1';f.querySelector('[name=enabled]').checked=b.dataset.enabled==='1';gatewayStatus.textContent=b.dataset.type==='vendo_gateway'?(b.dataset.paired==='1'?'Paired and connected':'Waiting for device pairing'):'Not paired';}else{f.querySelector('[name=enabled]').checked=true;gatewayStatus.textContent='Not paired';}document.getElementById('stationModalTitle').textContent=edit?'Edit station':'Add station';document.getElementById('station-submit').textContent=edit?'Save changes':'Add station';syncStationType();});
const stationGatewayUrl=document.getElementById('stationGatewayUrl');if(stationGatewayUrl)stationGatewayUrl.value=window.location.origin;document.getElementById('copyStationGatewayUrl')?.addEventListener('click',async e=>{try{await navigator.clipboard.writeText(stationGatewayUrl.value);const b=e.currentTarget,t=b.textContent;b.textContent='Copied';setTimeout(()=>b.textContent=t,1200);}catch{stationGatewayUrl.select();document.execCommand('copy');}});
</script>
<?php endif;?>